CREATE TABLE IF NOT EXISTS tiktok_profiles(workspace_id TEXT PRIMARY KEY REFERENCES workspaces(id),profile_id TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS tiktok_oauth(state_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL,workspace_id TEXT NOT NULL,profile_id TEXT NOT NULL,reconnect_id TEXT,expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS tiktok_accounts(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),remote_id TEXT NOT NULL UNIQUE,profile_id TEXT NOT NULL,native_id TEXT NOT NULL UNIQUE,name TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'connected',created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS tiktok_flows(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,account_id TEXT NOT NULL REFERENCES tiktok_accounts(id),name TEXT NOT NULL,trigger_type TEXT NOT NULL,keywords TEXT NOT NULL,graph TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 0,version INTEGER NOT NULL DEFAULT 1,published_at INTEGER,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS tiktok_events(id TEXT PRIMARY KEY,account_id TEXT NOT NULL,encrypted_event TEXT NOT NULL,event_at INTEGER NOT NULL,received_at INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'pending',lease_id TEXT,lease_until INTEGER,error TEXT);
CREATE TABLE IF NOT EXISTS tiktok_jobs(id TEXT PRIMARY KEY,event_id TEXT NOT NULL,workspace_id TEXT NOT NULL,account_id TEXT NOT NULL,flow_id TEXT NOT NULL,flow_version INTEGER NOT NULL,recipient_hash TEXT NOT NULL,conversation_hash TEXT NOT NULL,encrypted_action TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',due_at INTEGER NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,attempt_at INTEGER,completed_at INTEGER,lease_id TEXT,lease_until INTEGER,provider_id TEXT,error TEXT);
CREATE TABLE IF NOT EXISTS tiktok_contacts(account_id TEXT NOT NULL,recipient_hash TEXT NOT NULL,opted_out INTEGER NOT NULL DEFAULT 0,last_incoming_at INTEGER NOT NULL DEFAULT 0,last_event_at INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(account_id,recipient_hash));
CREATE TABLE IF NOT EXISTS tiktok_sessions(account_id TEXT NOT NULL,recipient_hash TEXT NOT NULL,flow_id TEXT NOT NULL,flow_version INTEGER NOT NULL,node_id TEXT NOT NULL,expires_at INTEGER NOT NULL,PRIMARY KEY(account_id,recipient_hash));
CREATE INDEX IF NOT EXISTS idx_tiktok_events_pending ON tiktok_events(status,event_at);
CREATE INDEX IF NOT EXISTS idx_tiktok_jobs_due ON tiktok_jobs(status,due_at);
CREATE INDEX IF NOT EXISTS idx_tiktok_conversation ON tiktok_jobs(account_id,conversation_hash,status,attempt_at);
CREATE TABLE IF NOT EXISTS tiktok_worker(id INTEGER PRIMARY KEY,lease TEXT NOT NULL,expires_at INTEGER NOT NULL);
